const briefDialog=document.querySelector('#brief-dialog');
const worldMenu=document.querySelector('.world-menu');worldMenu?.addEventListener('click',()=>{const open=document.querySelector('.world-header nav').classList.toggle('open');worldMenu.setAttribute('aria-expanded',open);worldMenu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')});document.querySelectorAll('.world-header nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.world-header nav').classList.remove('open');worldMenu?.setAttribute('aria-expanded','false');worldMenu?.setAttribute('aria-label','Открыть меню')}));
const modelDialog=document.querySelector('#model-dialog');
let dialogOpener;
document.querySelectorAll('[data-brief]').forEach(b=>b.addEventListener('click',()=>{dialogOpener=b;if(modelDialog?.open)modelDialog.close();briefDialog?.showModal()}));
document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>dialogOpener?.focus())});
document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const open=document.querySelector('.header nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);e.currentTarget.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')});
document.querySelectorAll('.header nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('.header nav').classList.remove('open');document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');document.querySelector('.menu-toggle')?.setAttribute('aria-label','Открыть меню')}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelectorAll('.character-card').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)}));
const config=window.NORMAS||{};
document.querySelectorAll('[data-contact]').forEach(a=>{let val=config[a.dataset.contact];if(!val)return;if(a.dataset.contact==='email'){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val))return;a.href='mailto:'+val}else{if(!/^https:\/\/t\.me\/[a-zA-Z0-9_]+\/?$/.test(val))return;a.href=val;a.target='_blank';a.rel='noopener noreferrer'}a.hidden=false});
const form=document.querySelector('#brief-form');
function briefing(){const d=Object.fromEntries(new FormData(form));return `БРИФ НА 3D-ПЕРСОНАЖА / NORMAS\n\nИмя: ${d.name}\nПрограмма: ${d.platform}\nЗадача: ${d.service}\n\nПерсонаж и референсы:\n${d.idea}\n\nБюджет: ${d.budget||'Обсудим'}\nЖелаемый срок: ${d.deadline||'Обсудим'}\n`}
function result(t){const el=document.querySelector('#brief-result');el.hidden=false;el.textContent=t}
form?.addEventListener('submit',e=>{e.preventDefault();const blob=new Blob([briefing()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='NORMAS-character-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);result('Бриф скачан. Отправь этот файл студии, чтобы обсудить проект.')});
document.querySelector('#copy-brief')?.addEventListener('click',async()=>{if(!form.reportValidity())return;try{await navigator.clipboard.writeText(briefing());result('Бриф скопирован. Вставь его в сообщение студии.')}catch{result('Браузер не разрешил копирование. Используй кнопку «Скачать бриф».')}});
